event.result:
:root{
  --bg:#0a0e17;
  --bg-panel:#0f1420;
  --bg-panel-2:#121826;
  --grid:rgba(255,176,0,0.075);
  --grid-strong:rgba(255,176,0,0.16);
  --amber:#ffb000;
  --amber-dim:#c98d1f;
  --cyan:#54e0cf;
  --cyan-dim:#2f9c8f;
  --red:#ff6459;
  --text:#e8ecf3;
  --text-dim:#94a0b4;
  --text-dimmer:#5c6a80;
  --line:#232b3a;
  --serif-display: 'Space Grotesk', sans-serif;
  --sans: 'IBM Plex Sans', sans-serif;
  --mono: 'IBM Plex Mono', monospace;
}

html[data-theme="light"]{
  --bg:#f7f4ed;
  --bg-panel:#ffffff;
  --bg-panel-2:#efede6;
  --grid:rgba(104,77,21,0.075);
  --grid-strong:rgba(104,77,21,0.14);
  --amber:#a96300;
  --amber-dim:#80541a;
  --cyan:#087b72;
  --cyan-dim:#3b8f88;
  --red:#c63d34;
  --text:#17202c;
  --text-dim:#566275;
  --text-dimmer:#748095;
  --line:#d9d5ca;
}

*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{
  margin:0;
  background:var(--bg);
  color:var(--text);
  font-family:var(--sans);
  line-height:1.65;
  font-size:16.5px;
  transition:background-color .2s ease,color .2s ease;
}

/* subtle grid texture across whole page */
body::before{
  content:"";
  position:fixed; inset:0;
  background-image:
    linear-gradient(var(--grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid) 1px, transparent 1px);
  background-size:32px 32px;
  pointer-events:none;
  z-index:0;
  opacity:0.5;
}

#progress{
  position:fixed; top:0; left:0; height:3px; width:0%;
  background:linear-gradient(90deg, var(--amber), var(--cyan));
  z-index:200;
  transition:width .08s linear;
}

a{color:var(--cyan);}

h1,h2,h3,h4{
  font-family:var(--serif-display);
  font-weight:600;
  color:var(--text);
  letter-spacing:-0.01em;
}

.eyebrow{
  font-family:var(--mono);
  font-size:12.5px;
  letter-spacing:0.14em;
  text-transform:uppercase;
  color:var(--amber);
}

/* ---------- TOC ---------- */
#toc-toggle{
  display:none;
  position:fixed; top:14px; right:14px; z-index:210;
  background:var(--bg-panel-2); border:1px solid var(--line);
  color:var(--amber); font-family:var(--mono); font-size:13px;
  padding:8px 12px; border-radius:6px; cursor:pointer;
}

#theme-toggle{
  position:fixed; top:14px; right:16px; z-index:210;
  background:var(--bg-panel-2); border:1px solid var(--line);
  color:var(--text); font-family:var(--mono); font-size:12px;
  padding:8px 11px; border-radius:6px; cursor:pointer;
  box-shadow:0 3px 14px rgba(0,0,0,.12);
}
#theme-toggle:hover{ color:var(--amber); border-color:var(--amber-dim); }
#theme-toggle:focus-visible{ outline:2px solid var(--cyan); outline-offset:2px; }

nav.toc{
  position:fixed; top:0; left:0; height:100vh; width:238px;
  background:var(--bg-panel);
  border-right:1px solid var(--line);
  padding:26px 20px;
  overflow-y:auto;
  z-index:150;
}
nav.toc .toc-brand{
  font-family:var(--mono); font-size:11px; color:var(--text-dimmer);
  letter-spacing:0.12em; text-transform:uppercase; margin-bottom:22px;
}
nav.toc .toc-mod{ margin-bottom:18px; }
nav.toc .toc-mod > a{
  display:block; font-family:var(--serif-display); font-size:14px;
  font-weight:600; color:var(--text); text-decoration:none;
  padding:4px 0; border-left:2px solid transparent; padding-left:10px;
}
nav.toc .toc-mod > a:hover, nav.toc .toc-mod > a.active{
  color:var(--amber); border-left-color:var(--amber);
}
nav.toc .toc-sub{ list-style:none; margin:2px 0 0; padding:0 0 0 10px; }
nav.toc .toc-sub li a{
  display:block; font-family:var(--mono); font-size:11.5px;
  color:var(--text-dimmer); text-decoration:none; padding:3px 0 3px 10px;
  border-left:1px solid var(--line);
}
nav.toc .toc-sub li a:hover{ color:var(--cyan); }

main{ margin-left:238px; position:relative; z-index:1; }

/* ---------- HERO ---------- */
.hero{
  padding:80px 64px 56px;
  border-bottom:1px solid var(--line);
  position:relative;
  overflow:hidden;
}
.hero .eyebrow{ margin-bottom:14px; }
.hero h1{
  font-size:44px; line-height:1.08; margin:0 0 16px; max-width:760px;
}
.hero p.lede{
  color:var(--text-dim); max-width:600px; font-size:17px; margin:0 0 34px;
}
.scope{
  position:relative;
  height:150px;
  max-width:760px;
  background:var(--bg-panel-2);
  border:1px solid var(--line);
  border-radius:8px;
  overflow:hidden;
}
.scope-grid{
  position:absolute; inset:0;
  background-image:
    linear-gradient(var(--grid-strong) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-strong) 1px, transparent 1px);
  background-size:38px 38px;
}
.scope-track{
  position:absolute; top:0; left:0; height:100%; width:200%;
  display:flex;
  animation:sweep 7s linear infinite;
}
.scope-track svg{ width:50%; height:100%; display:block; }
@keyframes sweep{ from{transform:translateX(0);} to{transform:translateX(-50%);} }
.scope-label{
  position:absolute; bottom:8px; left:12px;
  font-family:var(--mono); font-size:10.5px; color:var(--text-dimmer);
}

/* ---------- SECTIONS ---------- */
section{ padding:64px 64px 8px; max-width:920px; }
section .mod-number{
  font-family:var(--mono); color:var(--amber-dim); font-size:13px;
}
section > h2{ font-size:30px; margin:6px 0 6px; }
section > p.intro{ color:var(--text-dim); font-size:16px; max-width:680px; margin-bottom:36px; }

/* ---------- PEDAGOGICAL NAVIGATION ---------- */
.lesson-overview{ padding-top:40px; }
.outcome-grid{
  display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:14px;
  margin:22px 0 30px;
}
.outcome-card{
  background:var(--bg-panel); border:1px solid var(--line); border-radius:8px;
  padding:17px 18px;
}
.outcome-card .outcome-kicker{
  display:block; color:var(--amber); font:11px var(--mono);
  letter-spacing:.08em; text-transform:uppercase; margin-bottom:6px;
}
.outcome-card p{ color:var(--text-dim); font-size:14px; margin:0; }
.lesson-roadmap{
  display:grid; grid-template-columns:repeat(5,minmax(120px,1fr));
  gap:8px; margin:24px 0 32px; overflow-x:auto; padding-bottom:6px;
}
.roadmap-stage{
  position:relative; min-height:128px; padding:15px 14px;
  background:var(--bg-panel-2); border:1px solid var(--line); border-radius:8px;
}
.roadmap-stage:not(:last-child)::after{
  content:"→"; position:absolute; right:-9px; top:48px; z-index:2;
  color:var(--amber); font:18px var(--mono);
}
.roadmap-stage .stage-number{ color:var(--cyan); font:11px var(--mono); }
.roadmap-stage strong{ display:block; margin:5px 0; font-size:14px; }
.roadmap-stage small{ display:block; color:var(--text-dimmer); line-height:1.45; }
.checkpoint{
  margin:30px 0 10px; padding:18px 20px; border:1px dashed var(--cyan-dim);
  border-radius:8px; background:rgba(84,224,207,.035);
}
.checkpoint h4{
  color:var(--cyan); font:12px var(--mono); text-transform:uppercase;
  letter-spacing:.07em; margin:0 0 8px;
}
.checkpoint ul{ color:var(--text-dim); font-size:14px; margin-bottom:0; }
.assumption-strip{
  display:flex; flex-wrap:wrap; gap:8px; margin:14px 0 22px;
}
.assumption-strip span{
  border:1px solid var(--line); background:var(--bg-panel-2); border-radius:999px;
  padding:5px 10px; color:var(--text-dim); font:11px var(--mono);
}

/* ---------- SEMANTIC FIGURES AND FLOWS ---------- */
figure.teaching-figure{
  margin:24px 0 32px; padding:18px; background:var(--bg-panel);
  border:1px solid var(--line); border-radius:9px; overflow-x:auto;
}
figure.teaching-figure svg{ display:block; width:100%; height:auto; min-width:560px; }
figure.teaching-figure figcaption{
  max-width:720px; margin:12px auto 0; color:var(--text-dimmer);
  text-align:center; font:11.5px/1.5 var(--mono);
}
.signal-flow{
  display:flex; align-items:stretch; gap:8px; margin:22px 0 30px;
  overflow-x:auto; padding:4px 2px 10px;
}
.flow-node{
  flex:1 0 120px; min-height:98px; padding:13px 12px;
  border:1px solid var(--line); border-radius:7px; background:var(--bg-panel);
}
.flow-node strong{ display:block; color:var(--amber); font:12px var(--mono); margin-bottom:5px; }
.flow-node small{ color:var(--text-dimmer); line-height:1.4; }
.flow-arrow{ align-self:center; color:var(--cyan); font:18px var(--mono); }
.decision-table td:first-child{ color:var(--amber); font-family:var(--mono); }

h3.subhead{
  font-family:var(--serif-display); font-size:20px; font-weight:600;
  margin:44px 0 6px; padding-top:10px; border-top:1px solid var(--line);
  display:flex; align-items:baseline; gap:10px;
}
h3.subhead .tag{
  font-family:var(--mono); font-size:12px; color:var(--cyan); font-weight:400;
}

p{ margin:0 0 16px; }
ul, ol{ margin:0 0 20px; padding-left:22px; }
li{ margin-bottom:6px; }
strong{ color:var(--text); font-weight:600;}
em.term{ font-style:normal; color:var(--amber); font-weight:500;}

/* definition cards */
.def-grid{
  display:grid; grid-template-columns:1fr 1fr; gap:14px;
  margin:26px 0 34px;
}
.def-card{
  background:var(--bg-panel); border:1px solid var(--line);
  border-radius:8px; padding:16px 18px;
}
.def-card .dt{
  font-family:var(--mono); font-size:12px; color:var(--amber);
  text-transform:uppercase; letter-spacing:.06em; margin-bottom:6px;
}
.def-card .dd{ font-size:14.5px; color:var(--text-dim); }

/* block diagram */
.block-diagram{
  display:flex; align-items:center; gap:0; flex-wrap:wrap;
  background:var(--bg-panel); border:1px solid var(--line); border-radius:10px;
  padding:34px 22px 22px; margin:28px 0 34px; position:relative;
}
.blk{
  font-family:var(--mono); font-size:12.5px; text-align:center;
  background:var(--bg-panel-2); border:1px solid var(--line);
  border-radius:6px; padding:12px 14px; color:var(--text);
  min-width:96px;
}
.blk small{ display:block; color:var(--text-dimmer); font-size:10px; margin-top:3px;}
.arrow{ color:var(--amber-dim); font-size:18px; padding:0 8px; }
.noise-drop{
  position:absolute; top:2px; left:50%; transform:translateX(-50%);
  font-family:var(--mono); font-size:11px; color:var(--red);
}
.noise-drop::after{
  content:""; display:block; width:1px; height:16px; background:var(--red);
  margin:2px auto 0; opacity:0.6;
}

/* equation blocks */
.eq-block{
  background:var(--bg-panel); border:1px solid var(--line); border-left:3px solid var(--amber-dim);
  border-radius:6px; padding:18px 22px; margin:18px 0; overflow-x:auto;
}
.eq-block .eq-label{
  font-family:var(--mono); font-size:11px; color:var(--text-dimmer);
  margin-bottom:8px; text-transform:uppercase; letter-spacing:.05em;
}
.step{
  display:flex; gap:14px; margin:22px 0;
  padding-left:2px;
}
.step .num{
  font-family:var(--mono); color:var(--cyan); font-size:13px;
  min-width:26px; padding-top:4px;
}
.step .body{ flex:1; }
.step .body .why{
  color:var(--text-dimmer); font-size:13.5px; margin-top:6px;
}
.step .body .why::before{ content:"Por quê? "; color:var(--cyan); font-family:var(--mono); font-size:11px; }

/* scope diagrams for waveforms */
.diagram-scope{
  background:var(--bg-panel-2); border:1px solid var(--line); border-radius:8px;
  padding:10px 10px 6px; margin:14px 0 8px;
}
html[data-theme="light"] .diagram-scope{
  /* Existing SVGs use oscilloscope colors; keep their canvas dark. */
  background:#121826; border-color:#303949;
}
html[data-theme="light"] .scope{ background:#121826; border-color:#303949; }
html[data-theme="light"] nav.toc{ box-shadow:2px 0 14px rgba(25,30,40,.05); }
.diagram-scope svg{ width:100%; height:auto; display:block; }
.diagram-caption{
  font-family:var(--mono); font-size:11.5px; color:var(--text-dimmer);
  text-align:center; margin-bottom:14px;
}
.phasor-wrap{
  display:grid; grid-template-columns:minmax(280px,1fr) minmax(220px,.7fr);
  gap:18px; align-items:center; margin:22px 0 30px;
}
.phasor-notes{ color:var(--text-dim); font-size:14px; }
.phasor-notes ol{ margin-bottom:0; }
.trace-amber{ stroke:var(--amber); }
.trace-cyan{ stroke:var(--cyan); }
.trace-dim{ stroke:var(--text-dimmer); stroke-dasharray:3 3; }

/* callouts */
.callout{
  border-radius:8px; padding:16px 18px; margin:22px 0;
  font-size:14.5px; border:1px solid;
}
.callout.note{ background:rgba(84,224,207,0.06); border-color:var(--cyan-dim); }
.callout.warn{ background:rgba(255,100,89,0.07); border-color:var(--red); }
.callout .ct{
  font-family:var(--mono); font-size:11px; text-transform:uppercase;
  letter-spacing:.08em; margin-bottom:6px;
}
.callout.note .ct{ color:var(--cyan); }
.callout.warn .ct{ color:var(--red); }

/* mathematical statements */
.math-box{
  background:linear-gradient(135deg,rgba(84,224,207,.055),var(--bg-panel) 65%);
  border:1px solid var(--line); border-left:3px solid var(--cyan);
  border-radius:7px; padding:18px 20px; margin:22px 0;
}
.math-box.proof{ border-left-color:var(--amber); background:var(--bg-panel); }
.math-box.insight{ border-left-color:var(--text-dimmer); }
.math-title{
  font-family:var(--mono); font-size:11px; color:var(--cyan);
  text-transform:uppercase; letter-spacing:.08em; margin-bottom:8px;
}
.math-box.proof .math-title{ color:var(--amber); }
.math-box.insight .math-title{ color:var(--text-dim); }
.qed{ float:right; color:var(--amber); font-family:var(--mono); }
.exercise{
  background:var(--bg-panel); border:1px solid var(--line); border-radius:8px;
  padding:18px 20px; margin:16px 0;
}
.exercise .ex-title{ font-family:var(--mono); color:var(--amber); font-size:12px; margin-bottom:8px; }
details.solution{ margin-top:12px; border-top:1px dashed var(--line); padding-top:10px; }
details.solution summary{ cursor:pointer; color:var(--cyan); font-family:var(--mono); font-size:12px; }
details.solution > div{ padding-top:12px; color:var(--text-dim); }
.sim-grid{ display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; margin:24px 0 34px; }
.sim-card{ background:var(--bg-panel); border:1px solid var(--line); border-radius:9px; padding:18px; display:flex; flex-direction:column; }
.sim-card .sim-kicker{ color:var(--amber); font-family:var(--mono); font-size:11px; text-transform:uppercase; letter-spacing:.07em; }
.sim-card h3{ font-size:17px; margin:5px 0 8px; }
.sim-card p{ color:var(--text-dim); font-size:14px; flex:1; }
.sim-card ul{ color:var(--text-dimmer); font-size:13px; margin-bottom:14px; }
.sim-card a{ display:inline-block; align-self:flex-start; text-decoration:none; font-family:var(--mono); font-size:12px; color:var(--bg); background:var(--cyan); padding:8px 12px; border-radius:5px; font-weight:600; }
.sim-card a:hover{ filter:brightness(1.08); transform:translateY(-1px); }

/* comparison table */
table{ width:100%; border-collapse:collapse; margin:22px 0 30px; font-size:14px; }
th,td{ text-align:left; padding:10px 12px; border-bottom:1px solid var(--line); }
th{ font-family:var(--mono); font-size:11.5px; color:var(--text-dimmer); text-transform:uppercase; letter-spacing:.05em; font-weight:500;}
td strong{ color:var(--amber); }

.bw-bars{ margin:26px 0 30px; }
.bw-row{ display:flex; align-items:center; gap:14px; margin-bottom:12px; }
.bw-row .bw-name{ width:120px; font-family:var(--mono); font-size:12.5px; color:var(--text-dim); flex-shrink:0; }
.bw-row .bw-track{ flex:1; background:var(--bg-panel-2); border-radius:4px; height:20px; position:relative; overflow:hidden; }
.bw-row .bw-fill{ height:100%; border-radius:4px; }
.bw-row .bw-val{ width:64px; font-family:var(--mono); font-size:12px; color:var(--text-dimmer); text-align:right; flex-shrink:0;}

footer{
  padding:50px 64px 90px; color:var(--text-dimmer); font-size:13px;
  font-family:var(--mono); border-top:1px solid var(--line); margin-top:40px;
}

.katex-display{ margin:0.6em 0; }
.katex{ font-size:1.06em; color:var(--text); }

/* code blocks with highlight.js */
.code-block{
  background:#121826;
  border:1px solid var(--line);
  border-left:3px solid var(--cyan);
  border-radius:7px;
  margin:20px 0;
  overflow:hidden;
}
.code-block .code-title{
  background:rgba(84,224,207,.06);
  font-family:var(--mono);
  font-size:11px;
  color:var(--cyan);
  text-transform:uppercase;
  letter-spacing:.08em;
  padding:8px 14px;
  border-bottom:1px solid var(--line);
}
.code-block pre{
  margin:0;
  padding:16px 18px;
  overflow-x:auto;
  font-family:var(--mono);
  font-size:13.5px;
  line-height:1.55;
}
html[data-theme="light"] .code-block pre{
  background:#121826;
  color:#abb2bf;
}

@media (max-width:900px){
  nav.toc{ transform:translateX(-100%); transition:transform .25s ease; box-shadow:0 0 40px rgba(0,0,0,.5); }
  nav.toc.open{ transform:translateX(0); }
  #toc-toggle{ display:block; }
  #toc-toggle{ right:112px; }
  main{ margin-left:0; }
  .hero, section, footer{ padding-left:24px; padding-right:24px; }
  .def-grid{ grid-template-columns:1fr; }
  .sim-grid{ grid-template-columns:1fr; }
  .phasor-wrap{ grid-template-columns:1fr; }
  .outcome-grid{ grid-template-columns:1fr; }
  .lesson-roadmap{ grid-template-columns:repeat(5,minmax(150px,1fr)); }
  .hero h1{ font-size:32px; }
}

@media (prefers-reduced-motion:reduce){
  html{ scroll-behavior:auto; }
  .scope-track{ animation:none; }
  *{ transition-duration:.01ms !important; }
}

// light/dark theme toggle
(function(){
  const root = document.documentElement;
  const button = document.getElementById('theme-toggle');

  function syncThemeButton(){
    const isLight = root.dataset.theme === 'light';
    button.textContent = isLight ? '☾ Escuro' : '☀ Claro';
    button.setAttribute('aria-label', isLight ? 'Ativar fundo escuro' : 'Ativar fundo claro');
    button.setAttribute('aria-pressed', String(isLight));
    button.setAttribute('title', isLight ? 'Mudar para fundo escuro' : 'Mudar para fundo claro');
  }

  button.addEventListener('click', function(){
    const useLight = root.dataset.theme !== 'light';
    if (useLight) root.dataset.theme = 'light';
    else delete root.dataset.theme;
    try { localStorage.setItem('com-theme', useLight ? 'light' : 'dark'); } catch (_) {}
    syncThemeButton();
  });

  syncThemeButton();
})();

// progress bar
window.addEventListener('scroll', () => {
  const h = document.documentElement;
  const scrolled = (h.scrollTop) / (h.scrollHeight - h.clientHeight) * 100;
  document.getElementById('progress').style.width = scrolled + '%';
});

// ---------- waveform generation ----------
function pts(fn, tMin, tMax, N, w, h, yMid, yScale){
  const arr = [];
  for(let i=0;i<=N;i++){
    const t = tMin + (tMax-tMin)*i/N;
    const x = w*i/N;
    const y = yMid - yScale*fn(t);
    arr.push(x.toFixed(2)+','+y.toFixed(2));
  }
  return arr.join(' ');
}

const FM = 1;    // ciclos de mensagem na janela
const FC = 16;   // ciclos de portadora na janela
const message = t => Math.sin(2*Math.PI*FM*t);
const carrier = t => Math.cos(2*Math.PI*FC*t);
const amtc = (t,mu) => (1+mu*message(t))*Math.cos(2*Math.PI*FC*t);

// 4.1 message + carrier
document.getElementById('pl-message').setAttribute('points', pts(message,0,1,300,600,130,40,32));
document.getElementById('pl-carrier').setAttribute('points', pts(carrier,0,1,600,600,130,105,20));

// 4.2 three AM-TC panels (mu = 0.5, 1.0, 1.5)
(function(){
  const svg = document.getElementById('svg-amtc');
  const mus = [0.5,1.0,1.5];
  const labels = ['μ = 0.5 (submodulada)','μ = 1.0 (100%)','μ = 1.5 (sobremodulada)'];
  const panelW = 190, panelH = 150, gap = 15;
  mus.forEach((mu,i)=>{
    const xOff = i*(panelW+gap);
    const yMid = 75;
    const yScale = 24;
    const g = document.createElementNS('http://www.w3.org/2000/svg','g');
    g.setAttribute('transform', `translate(${xOff},0)`);

    const rect = document.createElementNS('http://www.w3.org/2000/svg','rect');
    rect.setAttribute('x',0); rect.setAttribute('y',0);
    rect.setAttribute('width',panelW); rect.setAttribute('height',panelH);
    rect.setAttribute('fill','none'); rect.setAttribute('stroke','#232b3a');
    g.appendChild(rect);

    // envelope upper/lower dashed
    const envU = document.createElementNS('http://www.w3.org/2000/svg','polyline');
    envU.setAttribute('points', pts(t=>1+mu*message(t),0,1,300,panelW,panelH,yMid,yScale));
    envU.setAttribute('fill','none'); envU.setAttribute('class','trace-dim'); envU.setAttribute('stroke-width','1');
    g.appendChild(envU);
    const envL = document.createElementNS('http://www.w3.org/2000/svg','polyline');
    envL.setAttribute('points', pts(t=>-(1+mu*message(t)),0,1,300,panelW,panelH,yMid,yScale));
    envL.setAttribute('fill','none'); envL.setAttribute('class','trace-dim'); envL.setAttribute('stroke-width','1');
    g.appendChild(envL);

    const wave = document.createElementNS('http://www.w3.org/2000/svg','polyline');
    wave.setAttribute('points', pts(t=>amtc(t,mu),0,1,600,panelW,panelH,yMid,yScale));
    wave.setAttribute('fill','none');
    wave.setAttribute('stroke', mu>1 ? 'var(--red)' : 'var(--amber)');
    wave.setAttribute('stroke-width','1.3');
    g.appendChild(wave);

    const text = document.createElementNS('http://www.w3.org/2000/svg','text');
    text.setAttribute('x',6); text.setAttribute('y',14);
    text.setAttribute('font-family','IBM Plex Mono'); text.setAttribute('font-size','10');
    text.setAttribute('fill', mu>1 ? '#ff6459' : '#5c6a80');
    text.textContent = labels[i];
    g.appendChild(text);

    svg.appendChild(g);
  });
})();

// 4.3 spectrum lollipop diagram
(function(){
  const svg = document.getElementById('svg-spectrum');
  const w=600,h=190, mid=300, baseY=150;
  const fcPx = 60; // px distance representing f_m offset
  const mu = 0.6;
  const carrierH = 110;
  const sbH = carrierH*mu/2;

  function axisLine(x1,y1,x2,y2,color,width){
    const l = document.createElementNS('http://www.w3.org/2000/svg','line');
    l.setAttribute('x1',x1); l.setAttribute('y1',y1);
    l.setAttribute('x2',x2); l.setAttribute('y2',y2);
    l.setAttribute('stroke',color); l.setAttribute('stroke-width',width);
    svg.appendChild(l);
  }
  function label(x,y,t,color,anchor){
    const txt = document.createElementNS('http://www.w3.org/2000/svg','text');
    txt.setAttribute('x',x); txt.setAttribute('y',y);
    txt.setAttribute('font-family','IBM Plex Mono'); txt.setAttribute('font-size','11');
    txt.setAttribute('fill',color); txt.setAttribute('text-anchor', anchor||'middle');
    txt.textContent = t;
    svg.appendChild(txt);
  }

  // axis
  axisLine(20,baseY,580,baseY,'#232b3a',1);
  label(300,175,'f',  '#5c6a80');

  // negative side (mirror) faint
  [-1,1].forEach(sign=>{
    const cx = mid + sign*160;
    axisLine(cx, baseY, cx, baseY-carrierH, '#ffb000', 2.5);
    label(cx, baseY-carrierH-10, sign>0 ? 'f_c' : '-f_c', '#ffb000');

    axisLine(cx-fcPx, baseY, cx-fcPx, baseY-sbH, '#54e0cf', 2.5);
    axisLine(cx+fcPx, baseY, cx+fcPx, baseY-sbH, '#54e0cf', 2.5);
    label(cx-fcPx, baseY-sbH-8, sign>0 ? 'f_c-f_m' : '', '#54e0cf');
    label(cx+fcPx, baseY-sbH-8, sign>0 ? 'f_c+f_m' : '', '#54e0cf');
  });
})();

// 5.3 Bessel spectrum lollipop diagram (FM tonal, beta = 2)
(function(){
  const svg = document.getElementById('svg-fm-time');
  if(!svg) return;
  const NS='http://www.w3.org/2000/svg', width=700, panelH=88;
  const labels=['mensagem  m(t)','frequência  f_i(t)','sinal FM  s(t)'];
  const colors=['#54e0cf','#ffb000','#e8ecf3'];
  function line(x1,y1,x2,y2,stroke='#232b3a',dash=''){
    const e=document.createElementNS(NS,'line');
    Object.entries({x1,y1,x2,y2,stroke}).forEach(([k,v])=>e.setAttribute(k,v));
    if(dash)e.setAttribute('stroke-dasharray',dash); svg.appendChild(e);
  }
  function label(x,y,value,color='#94a0b4'){
    const e=document.createElementNS(NS,'text'); e.setAttribute('x',x); e.setAttribute('y',y);
    e.setAttribute('fill',color); e.setAttribute('font-family','IBM Plex Mono'); e.setAttribute('font-size','11');
    e.textContent=value; svg.appendChild(e);
  }
  function path(fn,yMid,scale,color){
    const points=[]; for(let i=0;i<=900;i++){const t=i/900; points.push(`${70+610*t},${yMid-scale*fn(t)}`);}
    const e=document.createElementNS(NS,'polyline'); e.setAttribute('points',points.join(' ')); e.setAttribute('fill','none');
    e.setAttribute('stroke',color); e.setAttribute('stroke-width','1.7'); svg.appendChild(e);
  }
  for(let p=0;p<3;p++){const y=55+p*panelH; line(65,y,685,y); label(8,y-30,labels[p],colors[p]);}
  for(let k=0;k<=4;k++){const x=70+k*152.5; line(x,18,x,300,'#232b3a','3 5');}
  const msg=t=>Math.sin(2*Math.PI*t), fi=t=>Math.sin(2*Math.PI*t);
  path(msg,55,30,colors[0]); path(fi,143,30,colors[1]);
  path(t=>Math.cos(2*Math.PI*(13*t-(3/(2*Math.PI))*Math.cos(2*Math.PI*t))),231,29,colors[2]);
  label(610,118,'f_c + Δf','#ffb000'); label(610,170,'f_c − Δf','#ffb000');
  label(650,318,'tempo →','#5c6a80');
})();

// 5.3 Bessel spectrum lollipop diagram (FM tonal, beta = 2)
(function(){
  const svg = document.getElementById('svg-bessel-spectrum');
  if(!svg) return;

  // Bessel function of the first kind, order n, via its power series (converges fast for small beta).
  function besselJ(n, x){
    n = Math.abs(n);
    let term = Math.pow(x/2, n) / factorial(n);
    let sum = term;
    for(let k=1; k<=40; k++){
      term *= -(x*x/4) / (k*(k+n));
      sum += term;
      if(Math.abs(term) < 1e-14) break;
    }
    return sum;
  }
  function factorial(n){ let r=1; for(let i=2;i<=n;i++) r*=i; return r; }
  function jn(n, x){
    // J_{-n}(x) = (-1)^n J_n(x)
    return n>=0 ? besselJ(n,x) : Math.pow(-1,-n)*besselJ(-n,x);
  }

  const beta = 2;
  const w=600,h=200, mid=300, baseY=165, pxPerLine=32, maxH=120;
  const nMax = 6; // display -6..+6 (amplitudes beyond this are negligible for beta=2)

  function axisLine(x1,y1,x2,y2,color,width){
    const l = document.createElementNS('http://www.w3.org/2000/svg','line');
    l.setAttribute('x1',x1); l.setAttribute('y1',y1);
    l.setAttribute('x2',x2); l.setAttribute('y2',y2);
    l.setAttribute('stroke',color); l.setAttribute('stroke-width',width);
    svg.appendChild(l);
  }
  function label(x,y,t,color,size){
    const txt = document.createElementNS('http://www.w3.org/2000/svg','text');
    txt.setAttribute('x',x); txt.setAttribute('y',y);
    txt.setAttribute('font-family','IBM Plex Mono'); txt.setAttribute('font-size',size||10);
    txt.setAttribute('fill',color); txt.setAttribute('text-anchor','middle');
    txt.textContent = t;
    svg.appendChild(txt);
  }

  axisLine(20, baseY, 580, baseY, '#232b3a', 1);
  label(300, 190, 'f', '#5c6a80', 11);
  label(90, 30, 'β = 2', '#e8ecf3', 13);

  for(let n=-nMax; n<=nMax; n++){
    const val = jn(n, beta);
    const x = mid + n*pxPerLine;
    const hgt = Math.abs(val)*maxH;
    const color = n===0 ? '#ffb000' : '#54e0cf';
    axisLine(x, baseY, x, baseY-hgt, color, n===0?2.8:2.2);
    if(Math.abs(val) > 0.03){
      label(x, baseY-hgt-6, val.toFixed(2), val<0 ? '#ff6459' : color, 9);
    }
    if(n===0) label(x, baseY+14, 'f_c', '#5c6a80', 10);
    else if(Math.abs(n)<=3) label(x, baseY+14, (n>0?'f_c+'+n+'f_m':'f_c'+n+'f_m'), '#5c6a80', 8.5);
  }
})();

// scope hero sweep track: two tiled AM waveforms
(function(){
  const track = document.getElementById('scope-track');
  for(let k=0;k<2;k++){
    const svg = document.createElementNS('http://www.w3.org/2000/svg','svg');
    svg.setAttribute('viewBox','0 0 400 150');
    svg.setAttribute('preserveAspectRatio','none');
    const poly = document.createElementNS('http://www.w3.org/2000/svg','polyline');
    poly.setAttribute('points', pts(t=>amtc(t,0.6),0,1,500,400,150,75,44));
    poly.setAttribute('fill','none');
    poly.setAttribute('stroke','#ffb000');
    poly.setAttribute('stroke-width','1.6');
    svg.appendChild(poly);
    track.appendChild(svg);
  }
})();

// active TOC highlight
const secs = document.querySelectorAll('section, header.hero');
const links = document.querySelectorAll('nav.toc .toc-mod > a');
window.addEventListener('scroll', () => {
  let current = '';
  secs.forEach(s => { if (scrollY >= s.offsetTop - 120) current = s.id; });
  links.forEach(a => a.classList.toggle('active', a.getAttribute('href') === '#'+current));
});

// KaTeX render
document.addEventListener('DOMContentLoaded', function() {
  renderMathInElement(document.body, {
    delimiters: [
      {left: '$$', right: '$$', display: true},
      {left: '\\[', right: '\\]', display: true},
      {left: '\\(', right: '\\)', display: false},
      {left: '\\(', right: '\\)', display: false}
    ],
    throwOnError: false
  });
});

toolResults.content:
:root{
  --bg:#0a0e17;
  --bg-panel:#0f1420;
  --bg-panel-2:#121826;
  --grid:rgba(255,176,0,0.075);
  --grid-strong:rgba(255,176,0,0.16);
  --amber:#ffb000;
  --amber-dim:#c98d1f;
  --cyan:#54e0cf;
  --cyan-dim:#2f9c8f;
  --red:#ff6459;
  --text:#e8ecf3;
  --text-dim:#94a0b4;
  --text-dimmer:#5c6a80;
  --line:#232b3a;
  --serif-display: 'Space Grotesk', sans-serif;
  --sans: 'IBM Plex Sans', sans-serif;
  --mono: 'IBM Plex Mono', monospace;
}

html[data-theme="light"]{
  --bg:#f7f4ed;
  --bg-panel:#ffffff;
  --bg-panel-2:#efede6;
  --grid:rgba(104,77,21,0.075);
  --grid-strong:rgba(104,77,21,0.14);
  --amber:#a96300;
  --amber-dim:#80541a;
  --cyan:#087b72;
  --cyan-dim:#3b8f88;
  --red:#c63d34;
  --text:#17202c;
  --text-dim:#566275;
  --text-dimmer:#748095;
  --line:#d9d5ca;
}

*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{
  margin:0;
  background:var(--bg);
  color:var(--text);
  font-family:var(--sans);
  line-height:1.65;
  font-size:16.5px;
  transition:background-color .2s ease,color .2s ease;
}

/* subtle grid texture across whole page */
body::before{
  content:"";
  position:fixed; inset:0;
  background-image:
    linear-gradient(var(--grid) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid) 1px, transparent 1px);
  background-size:32px 32px;
  pointer-events:none;
  z-index:0;
  opacity:0.5;
}

#progress{
  position:fixed; top:0; left:0; height:3px; width:0%;
  background:linear-gradient(90deg, var(--amber), var(--cyan));
  z-index:200;
  transition:width .08s linear;
}

a{color:var(--cyan);}

h1,h2,h3,h4{
  font-family:var(--serif-display);
  font-weight:600;
  color:var(--text);
  letter-spacing:-0.01em;
}

.eyebrow{
  font-family:var(--mono);
  font-size:12.5px;
  letter-spacing:0.14em;
  text-transform:uppercase;
  color:var(--amber);
}

/* ---------- TOC ---------- */
#toc-toggle{
  display:none;
  position:fixed; top:14px; right:14px; z-index:210;
  background:var(--bg-panel-2); border:1px solid var(--line);
  color:var(--amber); font-family:var(--mono); font-size:13px;
  padding:8px 12px; border-radius:6px; cursor:pointer;
}

#theme-toggle{
  position:fixed; top:14px; right:16px; z-index:210;
  background:var(--bg-panel-2); border:1px solid var(--line);
  color:var(--text); font-family:var(--mono); font-size:12px;
  padding:8px 11px; border-radius:6px; cursor:pointer;
  box-shadow:0 3px 14px rgba(0,0,0,.12);
}
#theme-toggle:hover{ color:var(--amber); border-color:var(--amber-dim); }
#theme-toggle:focus-visible{ outline:2px solid var(--cyan); outline-offset:2px; }

nav.toc{
  position:fixed; top:0; left:0; height:100vh; width:238px;
  background:var(--bg-panel);
  border-right:1px solid var(--line);
  padding:26px 20px;
  overflow-y:auto;
  z-index:150;
}
nav.toc .toc-brand{
  font-family:var(--mono); font-size:11px; color:var(--text-dimmer);
  letter-spacing:0.12em; text-transform:uppercase; margin-bottom:22px;
}
nav.toc .toc-mod{ margin-bottom:18px; }
nav.toc .toc-mod > a{
  display:block; font-family:var(--serif-display); font-size:14px;
  font-weight:600; color:var(--text); text-decoration:none;
  padding:4px 0; border-left:2px solid transparent; padding-left:10px;
}
nav.toc .toc-mod > a:hover, nav.toc .toc-mod > a.active{
  color:var(--amber); border-left-color:var(--amber);
}
nav.toc .toc-sub{ list-style:none; margin:2px 0 0; padding:0 0 0 10px; }
nav.toc .toc-sub li a{
  display:block; font-family:var(--mono); font-size:11.5px;
  color:var(--text-dimmer); text-decoration:none; padding:3px 0 3px 10px;
  border-left:1px solid var(--line);
}
nav.toc .toc-sub li a:hover{ color:var(--cyan); }

main{ margin-left:238px; position:relative; z-index:1; }

/* ---------- HERO ---------- */
.hero{
  padding:80px 64px 56px;
  border-bottom:1px solid var(--line);
  position:relative;
  overflow:hidden;
}
.hero .eyebrow{ margin-bottom:14px; }
.hero h1{
  font-size:44px; line-height:1.08; margin:0 0 16px; max-width:760px;
}
.hero p.lede{
  color:var(--text-dim); max-width:600px; font-size:17px; margin:0 0 34px;
}
.scope{
  position:relative;
  height:150px;
  max-width:760px;
  background:var(--bg-panel-2);
  border:1px solid var(--line);
  border-radius:8px;
  overflow:hidden;
}
.scope-grid{
  position:absolute; inset:0;
  background-image:
    linear-gradient(var(--grid-strong) 1px, transparent 1px),
    linear-gradient(90deg, var(--grid-strong) 1px, transparent 1px);
  background-size:38px 38px;
}
.scope-track{
  position:absolute; top:0; left:0; height:100%; width:200%;
  display:flex;
  animation:sweep 7s linear infinite;
}
.scope-track svg{ width:50%; height:100%; display:block; }
@keyframes sweep{ from{transform:translateX(0);} to{transform:translateX(-50%);} }
.scope-label{
  position:absolute; bottom:8px; left:12px;
  font-family:var(--mono); font-size:10.5px; color:var(--text-dimmer);
}

/* ---------- SECTIONS ---------- */
section{ padding:64px 64px 8px; max-width:920px; }
section .mod-number{
  font-family:var(--mono); color:var(--amber-dim); font-size:13px;
}
section > h2{ font-size:30px; margin:6px 0 6px; }
section > p.intro{ color:var(--text-dim); font-size:16px; max-width:680px; margin-bottom:36px; }

/* ---------- PEDAGOGICAL NAVIGATION ---------- */
.lesson-overview{ padding-top:40px; }
.outcome-grid{
  display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:14px;
  margin:22px 0 30px;
}
.outcome-card{
  background:var(--bg-panel); border:1px solid var(--line); border-radius:8px;
  padding:17px 18px;
}
.outcome-card .outcome-kicker{
  display:block; color:var(--amber); font:11px var(--mono);
  letter-spacing:.08em; text-transform:uppercase; margin-bottom:6px;
}
.outcome-card p{ color:var(--text-dim); font-size:14px; margin:0; }
.lesson-roadmap{
  display:grid; grid-template-columns:repeat(5,minmax(120px,1fr));
  gap:8px; margin:24px 0 32px; overflow-x:auto; padding-bottom:6px;
}
.roadmap-stage{
  position:relative; min-height:128px; padding:15px 14px;
  background:var(--bg-panel-2); border:1px solid var(--line); border-radius:8px;
}
.roadmap-stage:not(:last-child)::after{
  content:"→"; position:absolute; right:-9px; top:48px; z-index:2;
  color:var(--amber); font:18px var(--mono);
}
.roadmap-stage .stage-number{ color:var(--cyan); font:11px var(--mono); }
.roadmap-stage strong{ display:block; margin:5px 0; font-size:14px; }
.roadmap-stage small{ display:block; color:var(--text-dimmer); line-height:1.45; }
.checkpoint{
  margin:30px 0 10px; padding:18px 20px; border:1px dashed var(--cyan-dim);
  border-radius:8px; background:rgba(84,224,207,.035);
}
.checkpoint h4{
  color:var(--cyan); font:12px var(--mono); text-transform:uppercase;
  letter-spacing:.07em; margin:0 0 8px;
}
.checkpoint ul{ color:var(--text-dim); font-size:14px; margin-bottom:0; }
.assumption-strip{
  display:flex; flex-wrap:wrap; gap:8px; margin:14px 0 22px;
}
.assumption-strip span{
  border:1px solid var(--line); background:var(--bg-panel-2); border-radius:999px;
  padding:5px 10px; color:var(--text-dim); font:11px var(--mono);
}

/* ---------- SEMANTIC FIGURES AND FLOWS ---------- */
figure.teaching-figure{
  margin:24px 0 32px; padding:18px; background:var(--bg-panel);
  border:1px solid var(--line); border-radius:9px; overflow-x:auto;
}
figure.teaching-figure svg{ display:block; width:100%; height:auto; min-width:560px; }
figure.teaching-figure figcaption{
  max-width:720px; margin:12px auto 0; color:var(--text-dimmer);
  text-align:center; font:11.5px/1.5 var(--mono);
}
.signal-flow{
  display:flex; align-items:stretch; gap:8px; margin:22px 0 30px;
  overflow-x:auto; padding:4px 2px 10px;
}
.flow-node{
  flex:1 0 120px; min-height:98px; padding:13px 12px;
  border:1px solid var(--line); border-radius:7px; background:var(--bg-panel);
}
.flow-node strong{ display:block; color:var(--amber); font:12px var(--mono); margin-bottom:5px; }
.flow-node small{ color:var(--text-dimmer); line-height:1.4; }
.flow-arrow{ align-self:center; color:var(--cyan); font:18px var(--mono); }
.decision-table td:first-child{ color:var(--amber); font-family:var(--mono); }

h3.subhead{
  font-family:var(--serif-display); font-size:20px; font-weight:600;
  margin:44px 0 6px; padding-top:10px; border-top:1px solid var(--line);
  display:flex; align-items:baseline; gap:10px;
}
h3.subhead .tag{
  font-family:var(--mono); font-size:12px; color:var(--cyan); font-weight:400;
}

p{ margin:0 0 16px; }
ul, ol{ margin:0 0 20px; padding-left:22px; }
li{ margin-bottom:6px; }
strong{ color:var(--text); font-weight:600;}
em.term{ font-style:normal; color:var(--amber); font-weight:500;}

/* definition cards */
.def-grid{
  display:grid; grid-template-columns:1fr 1fr; gap:14px;
  margin:26px 0 34px;
}
.def-card{
  background:var(--bg-panel); border:1px solid var(--line);
  border-radius:8px; padding:16px 18px;
}
.def-card .dt{
  font-family:var(--mono); font-size:12px; color:var(--amber);
  text-transform:uppercase; letter-spacing:.06em; margin-bottom:6px;
}
.def-card .dd{ font-size:14.5px; color:var(--text-dim); }

/* block diagram */
.block-diagram{
  display:flex; align-items:center; gap:0; flex-wrap:wrap;
  background:var(--bg-panel); border:1px solid var(--line); border-radius:10px;
  padding:34px 22px 22px; margin:28px 0 34px; position:relative;
}
.blk{
  font-family:var(--mono); font-size:12.5px; text-align:center;
  background:var(--bg-panel-2); border:1px solid var(--line);
  border-radius:6px; padding:12px 14px; color:var(--text);
  min-width:96px;
}
.blk small{ display:block; color:var(--text-dimmer); font-size:10px; margin-top:3px;}
.arrow{ color:var(--amber-dim); font-size:18px; padding:0 8px; }
.noise-drop{
  position:absolute; top:2px; left:50%; transform:translateX(-50%);
  font-family:var(--mono); font-size:11px; color:var(--red);
}
.noise-drop::after{
  content:""; display:block; width:1px; height:16px; background:var(--red);
  margin:2px auto 0; opacity:0.6;
}

/* equation blocks */
.eq-block{
  background:var(--bg-panel); border:1px solid var(--line); border-left:3px solid var(--amber-dim);
  border-radius:6px; padding:18px 22px; margin:18px 0; overflow-x:auto;
}
.eq-block .eq-label{
  font-family:var(--mono); font-size:11px; color:var(--text-dimmer);
  margin-bottom:8px; text-transform:uppercase; letter-spacing:.05em;
}
.step{
  display:flex; gap:14px; margin:22px 0;
  padding-left:2px;
}
.step .num{
  font-family:var(--mono); color:var(--cyan); font-size:13px;
  min-width:26px; padding-top:4px;
}
.step .body{ flex:1; }
.step .body .why{
  color:var(--text-dimmer); font-size:13.5px; margin-top:6px;
}
.step .body .why::before{ content:"Por quê? "; color:var(--cyan); font-family:var(--mono); font-size:11px; }

/* scope diagrams for waveforms */
.diagram-scope{
  background:var(--bg-panel-2); border:1px solid var(--line); border-radius:8px;
  padding:10px 10px 6px; margin:14px 0 8px;
}
